1	//! Parquet Writer
2	//!
3	//! High-level API for writing Parquet files.
4	//!
5	//! ## Example
6	//! ```zig
7	//! const parquet = @import("parquet");
8	//!
9	//! var writer = try parquet.Writer.init(allocator, file, &.{
10	//!     .{ .name = "id", .type = .int64, .optional = true },
11	//!     .{ .name = "name", .type = .byte_array, .optional = true },
12	//! });
13	//! defer writer.deinit();
14	//!
15	//! // Use writeColumnOptional for unified nullable/non-nullable handling
16	//! try writer.writeColumnOptional(i64, 0, &[_]parquet.Optional(i64){
17	//!     .{ .value = 1 }, .{ .value = 2 }, .{ .null_value = {} },
18	//! });
19	//! try writer.writeColumnOptional([]const u8, 1, &[_]parquet.Optional([]const u8){
20	//!     .{ .value = "a" }, .{ .null_value = {} }, .{ .value = "c" },
21	//! });
22	//!
23	//! try writer.close();
24	//! ```
25	
26	const std = @import("std");
27	const io = std.testing.io;
28	const safe = @import("safe.zig");
29	const format = @import("format.zig");
30	const thrift = @import("thrift/mod.zig");
31	const column_writer = @import("column_writer.zig");
32	const list_encoder = @import("list_encoder.zig");
33	const geo = @import("geo/mod.zig");
34	const statistics = @import("statistics.zig");
35	const map_encoder = @import("map_encoder.zig");
36	const types = @import("types.zig");
37	const schema_mod = @import("schema.zig");
38	const value_mod = @import("value.zig");
39	const nested_mod = @import("nested.zig");
40	const column_def_mod = @import("column_def.zig");
41	const write_target = @import("write_target.zig");
42	
43	const Optional = types.Optional;
44	const MapEntry = map_encoder.MapEntry;
45	pub const SchemaNode = schema_mod.SchemaNode;
46	pub const Value = value_mod.Value;
47	
48	// Re-export column definition types
49	pub const ColumnDef = column_def_mod.ColumnDef;
50	pub const StructField = column_def_mod.StructField;
51	
52	// Re-export write target types
53	pub const WriteTarget = write_target.WriteTarget;
54	pub const WriteTargetWriter = write_target.WriteTargetWriter;
55	pub const WriteError = write_target.WriteError;
56	pub const BackendCleanup = @import("parquet_reader.zig").BackendCleanup;
57	
58	
59	/// Writer state
60	const State = enum {
61	    initialized,
62	    writing_columns,
63	    closed,
64	};
65	
66	pub const WriterError = types.WriterError;
67	
68	/// Parquet file writer
69	pub const Writer = struct {
70	    allocator: std.mem.Allocator,
71	    target_writer: WriteTargetWriter,
72	    columns: []const ColumnDef,
73	    state: State,
74	    current_offset: i64,
75	    num_rows: ?i64,
76	
77	    num_physical_columns: usize,
78	    columns_written: []bool,
79	    column_chunks: []?format.ColumnChunk,
80	
81	    geo_stats_builders: std.AutoHashMapUnmanaged(usize, *statistics.GeospatialStatisticsBuilder),
82	
83	    sorting_columns: ?[]const format.SortingColumn = null,
84	
85	    _backend_cleanup: ?BackendCleanup = null,
86	    _to_owned_slice_fn: ?*const fn (*anyopaque) error{OutOfMemory}![]u8 = null,
87	    _to_owned_slice_ctx: ?*anyopaque = null,
88	
89	    const Self = @This();
90	
91	    /// Count total physical columns across all ColumnDefs
92	    fn countPhysicalColumns(columns: []const ColumnDef) usize {
93	        var count: usize = 0;
94	        for (columns) |col| {
95	            if (col.schema_node) |node| {
96	                // Use SchemaNode's leaf counting for complex nested types
97	                count += node.countLeafColumns();
98	            } else if (col.is_struct) {
99	                count += if (col.struct_fields) |fields| fields.len else 0;
100	            } else if (col.is_map) {
101	                count += 2; // Map has 2 physical columns: key and value
102	            } else if (col.is_list) {
103	                count += 1; // List is one physical column
104	            } else {
105	                count += 1;
106	            }
107	        }
108	        return count;
109	    }
110	
111	    /// Initialize geospatial statistics builders for geometry/geography columns
112	    fn initGeoStatsBuilders(
113	        allocator: std.mem.Allocator,
114	        columns: []const ColumnDef,
115	        builders: *std.AutoHashMapUnmanaged(usize, *statistics.GeospatialStatisticsBuilder),
116	    ) !void {
117	        errdefer {
118	            var it = builders.iterator();
119	            while (it.next()) |entry| {
120	                entry.value_ptr.*.deinit();
121	                allocator.destroy(entry.value_ptr.*);
122	            }
123	            builders.deinit(allocator);
124	        }
125	        for (columns, 0..) |col, idx| {
126	            if (col.logical_type) |lt| {
127	                switch (lt) {
128	                    .geometry, .geography => {
129	                        const builder = try allocator.create(statistics.GeospatialStatisticsBuilder);
130	                        errdefer allocator.destroy(builder);
131	                        builder.* = statistics.GeospatialStatisticsBuilder.init(allocator);
132	                        try builders.put(allocator, idx, builder);
133	                    },
134	                    else => {},
135	                }
136	            }
137	        }
138	    }
139	
140	    fn getPhysicalColumnIndex(self: *Self, col_def_index: usize, field_index: usize) WriterError!usize {
141	        if (col_def_index >= self.columns.len) return error.InvalidColumnIndex;
142	
143	        var physical_idx: usize = 0;
144	        for (self.columns[0..col_def_index]) |col| {
145	            if (col.schema_node) |node| {
146	                physical_idx += node.countLeafColumns();
147	            } else if (col.is_struct) {
148	                physical_idx += if (col.struct_fields) |fields| fields.len else 0;
149	            } else if (col.is_map) {
150	                physical_idx += 2;
151	            } else {
152	                physical_idx += 1;
153	            }
154	        }
155	
156	        const col_def = self.columns[col_def_index];
157	        if (col_def.schema_node) |node| {
158	            const leaf_count = node.countLeafColumns();
159	            if (field_index >= leaf_count) return error.InvalidColumnIndex;
160	            return physical_idx + field_index;
161	        } else if (col_def.is_struct) {
162	            const fields = col_def.struct_fields orelse return error.InvalidColumnIndex;
163	            if (field_index >= fields.len) return error.InvalidColumnIndex;
164	            return physical_idx + field_index;
165	        } else if (col_def.is_map) {
166	            if (field_index >= 2) return error.InvalidColumnIndex;
167	            return physical_idx + field_index;
168	        } else {
169	            if (field_index != 0) return error.InvalidColumnIndex;
170	            return physical_idx;
171	        }
172	    }
173	
174	    /// Initialize a writer with a WriteTarget. The caller manages target lifetime
175	    /// unless _backend_cleanup is set (by convenience constructors in api/zig/).
176	    pub fn initWithTarget(
177	        allocator: std.mem.Allocator,
178	        target: WriteTarget,
179	        columns: []const ColumnDef,
180	    ) WriterError!Self {
181	        target.write(format.PARQUET_MAGIC) catch return error.WriteError;
182	
183	        const num_physical = countPhysicalColumns(columns);
184	
185	        const columns_written = allocator.alloc(bool, num_physical) catch return error.OutOfMemory;
186	        errdefer allocator.free(columns_written);
187	        @memset(columns_written, false);
188	
189	        const column_chunks = allocator.alloc(?format.ColumnChunk, num_physical) catch return error.OutOfMemory;
190	        errdefer allocator.free(column_chunks);
191	        @memset(column_chunks, null);
192	
193	        var geo_stats_builders: std.AutoHashMapUnmanaged(usize, *statistics.GeospatialStatisticsBuilder) = .empty;
194	        initGeoStatsBuilders(allocator, columns, &geo_stats_builders) catch return error.OutOfMemory;
195	
196	        return Self{
197	            .allocator = allocator,
198	            .target_writer = WriteTargetWriter.init(target),
199	            .columns = columns,
200	            .state = .initialized,
201	            .current_offset = 4,
202	            .num_rows = null,
203	            .num_physical_columns = num_physical,
204	            .columns_written = columns_written,
205	            .column_chunks = column_chunks,
206	            .geo_stats_builders = geo_stats_builders,
207	        };
208	    }
209	
210	    fn getWriter(self: *Self) *std.Io.Writer {
211	        return self.target_writer.writer();
212	    }
213	
214	    fn flushWriter(self: *Self) WriterError!void {
215	        self.target_writer.flush() catch return error.WriteError;
216	    }
217	
218	    /// Clean up resources
219	    pub fn deinit(self: *Self) void {
220	        // Free column chunk metadata
221	        for (self.column_chunks) |*maybe_chunk| {
222	            if (maybe_chunk.*) |*chunk| {
223	                if (chunk.meta_data) |*md| {
224	                    self.allocator.free(md.encodings);
225	                    for (md.path_in_schema) |path| {
226	                        self.allocator.free(path);
227	                    }
228	                    self.allocator.free(md.path_in_schema);
229	                    // Free statistics if present
230	                    if (md.statistics) |stats| {
231	                        if (stats.min) |m| self.allocator.free(m);
232	                        if (stats.max) |m| self.allocator.free(m);
233	                        if (stats.min_value) |m| self.allocator.free(m);
234	                        if (stats.max_value) |m| self.allocator.free(m);
235	                    }
236	                    // Free geospatial statistics if present
237	                    if (md.geospatial_statistics) |geo_stats| {
238	                        if (geo_stats.geospatial_types) |gt| self.allocator.free(gt);
239	                    }
240	                }
241	            }
242	        }
243	        self.allocator.free(self.column_chunks);
244	        self.allocator.free(self.columns_written);
245	
246	        // Clean up geospatial statistics builders
247	        var iter = self.geo_stats_builders.iterator();
248	        while (iter.next()) |entry| {
249	            entry.value_ptr.*.deinit();
250	            self.allocator.destroy(entry.value_ptr.*);
251	        }
252	        self.geo_stats_builders.deinit(self.allocator);
253	
254	        if (self._backend_cleanup) |cleanup| {
255	            cleanup.deinit_fn(cleanup.ptr, self.allocator);
256	        }
257	    }
258	
259	    /// Map Zig type to Parquet PhysicalType at comptime
260	    fn physicalTypeFor(comptime T: type) format.PhysicalType {
261	        return if (T == i32) .int32
262	        else if (T == i64) .int64
263	        else if (T == f32) .float
264	        else if (T == f64) .double
265	        else if (T == bool) .boolean
266	        else if (T == []const u8) .byte_array
267	        else @compileError("Unsupported column type: " ++ @typeName(T));
268	    }
269	
270	    /// Write a column (non-nullable)
271	    /// Supports: i32, i64, f32, f64, bool, []const u8
272	    /// Deprecated: Use writeColumnOptional with Optional(T) instead.
273	    pub fn writeColumn(self: *Self, comptime T: type, column_index: usize, values: []const T) WriterError!void {
274	        // Convert to Optional and delegate to writeColumnOptional
275	        const optional_values = self.allocator.alloc(Optional(T), values.len) catch return error.OutOfMemory;
276	        defer self.allocator.free(optional_values);
277	        for (values, 0..) |v, i| {
278	            optional_values[i] = Optional(T).from(v);
279	        }
280	        return self.writeColumnOptional(T, column_index, optional_values);
281	    }
282	
283	    /// Write a nullable column
284	    /// Supports: i32, i64, f32, f64, bool, []const u8
285	    /// Deprecated: Use writeColumnOptional with Optional(T) instead.
286	    pub fn writeColumnNullable(self: *Self, comptime T: type, column_index: usize, values: []const ?T) WriterError!void {
287	        // Convert ?T to Optional(T) and delegate to writeColumnOptional
288	        const optional_values = self.allocator.alloc(Optional(T), values.len) catch return error.OutOfMemory;
289	        defer self.allocator.free(optional_values);
290	        for (values, 0..) |v, i| {
291	            optional_values[i] = Optional(T).from(v);
292	        }
293	        return self.writeColumnOptional(T, column_index, optional_values);
294	    }
295	
296	    /// Write a column with Optional values (unified API).
297	    /// This is the preferred method - accepts the same Optional(T) type that Reader returns.
298	    /// Works for both required and optional columns (uses schema to control def levels).
299	    /// Supports: i32, i64, f32, f64, bool, []const u8
300	    pub fn writeColumnOptional(self: *Self, comptime T: type, column_index: usize, values: []const Optional(T)) WriterError!void {
301	        const physical_type = comptime physicalTypeFor(T);
302	        // Pass false - Optional API works for both required and optional columns
303	        try self.validateColumnWrite(column_index, physical_type, false);
304	        const physical_idx = try self.getPhysicalColumnIndex(column_index, 0);
305	
306	        const col_def = self.columns[column_index];
307	        const writer = self.getWriter();
308	
309	        var result = if (T == []const u8)
310	            column_writer.writeColumnChunkByteArrayOptionalWithPathArray(
311	                self.allocator,
312	                writer,
313	                &.{col_def.name},
314	                values,
315	                col_def.optional,
316	                self.current_offset,
317	                col_def.codec,
318	                true, // write_page_checksum
319	            ) catch |e| return mapColumnError(e)
320	        else
321	            column_writer.writeColumnChunkOptionalWithPathArray(
322	                T,
323	                self.allocator,
324	                writer,
325	                &.{col_def.name},
326	                values,
327	                col_def.optional,
328	                self.current_offset,
329	                col_def.codec,
330	                true, // write_page_checksum
331	            ) catch |e| return mapColumnError(e);
332	
333	        // For byte_array geometry/geography columns, update bbox tracking
334	        if (T == []const u8) {
335	            if (col_def.logical_type) |lt| {
336	                switch (lt) {
337	                    .geometry, .geography => {
338	                        if (self.geo_stats_builders.get(column_index)) |builder| {
339	                            builder.updateOptional(values);
340	                        }
341	                    },
342	                    else => {},
343	                }
344	            }
345	        }
346	
347	        try self.flushWriter();
348	        try self.recordColumnWrite(physical_idx, &result, values.len);
349	    }
350	
351	    /// Write a fixed length byte array column (non-nullable)
352	    /// Deprecated: Use writeColumnFixedByteArrayOptional with Optional([]const u8) instead.
353	    pub fn writeColumnFixedByteArray(self: *Self, column_index: usize, values: []const []const u8) WriterError!void {
354	        // Convert to Optional and delegate to writeColumnFixedByteArrayOptional
355	        const optional_values = self.allocator.alloc(Optional([]const u8), values.len) catch return error.OutOfMemory;
356	        defer self.allocator.free(optional_values);
357	        for (values, 0..) |v, i| {
358	            optional_values[i] = Optional([]const u8).from(v);
359	        }
360	        return self.writeColumnFixedByteArrayOptional(column_index, optional_values);
361	    }
362	
363	    /// Write a fixed length byte array column with Optional values (unified API).
364	    /// This is the preferred method - accepts the same Optional type that Reader returns.
365	    /// Works for both required and optional columns (uses schema to control def levels).
366	    pub fn writeColumnFixedByteArrayOptional(self: *Self, column_index: usize, values: []const Optional([]const u8)) WriterError!void {
367	        // Pass false - Optional API works for both required and optional columns
368	        try self.validateColumnWrite(column_index, .fixed_len_byte_array, false);
369	        const physical_idx = try self.getPhysicalColumnIndex(column_index, 0);
370	
371	        const col_def = self.columns[column_index];
372	        const fixed_len = try safe.castTo(u32, col_def.type_length orelse return error.InvalidFixedLength);
373	        const writer = self.getWriter();
374	
375	        var result = column_writer.writeColumnChunkFixedByteArrayOptionalWithPathArrayAndEncoding(
376	            self.allocator,
377	            writer,
378	            &.{col_def.name},
379	            values,
380	            fixed_len,
381	            col_def.optional,
382	            self.current_offset,
383	            col_def.codec,
384	            col_def.value_encoding,
385	            true, // write_page_checksum
386	        ) catch |e| return mapColumnError(e);
387	
388	        // INTERVAL type: skip statistics (sort order undefined per Parquet spec)
389	        if (col_def.converted_type) |ct| {
390	            if (ct == format.ConvertedType.INTERVAL) {
391	                if (result.metadata.statistics) |stats| {
392	                    // Free the statistics memory
393	                    if (stats.min) |m| self.allocator.free(m);
394	                    if (stats.max) |m| self.allocator.free(m);
395	                    if (stats.min_value) |m| self.allocator.free(m);
396	                    if (stats.max_value) |m| self.allocator.free(m);
397	                }
398	                result.metadata.statistics = null;
399	            }
400	        }

1	//! Write Target Interface
2	//!
3	//! Provides a vtable-based interface for writing Parquet data to different backends.
4	//! This abstraction allows Writer and RowWriter to be backend-agnostic.
5	
6	const std = @import("std");
7	
8	/// Error type for write operations
9	pub const WriteError = error{
10	    WriteError,
11	    OutOfMemory,
12	    IntegerOverflow,
13	};
14	
15	/// Vtable-based interface for writing to different backends.
16	/// The Writer uses this interface to write Parquet data without knowing
17	/// the underlying storage mechanism.
18	pub const WriteTarget = struct {
19	    ptr: *anyopaque,
20	    vtable: *const VTable,
21	
22	    pub const VTable = struct {
23	        /// Write data to the target
24	        write: *const fn (ptr: *anyopaque, data: []const u8) WriteError!void,
25	        /// Close/finalize the target (flush buffers, complete uploads, etc.)
26	        close: *const fn (ptr: *anyopaque) WriteError!void,
27	    };
28	
29	    /// Write data to the target
30	    pub fn write(self: WriteTarget, data: []const u8) WriteError!void {
31	        return self.vtable.write(self.ptr, data);
32	    }
33	
34	    /// Close/finalize the target
35	    pub fn close(self: WriteTarget) WriteError!void {
36	        return self.vtable.close(self.ptr);
37	    }
38	};
39	
40	/// Adapter that bridges a `WriteTarget` vtable into a `*std.Io.Writer` interface.
41	///
42	/// Stores the `WriteTarget` and an unbuffered `std.Io.Writer` whose `drain`
43	/// forwards every write through `WriteTarget.write()`. This lets the column
44	/// writer pipeline (which requires `*std.Io.Writer`) work with any external
45	/// `WriteTarget` implementation (callbacks, custom sinks, etc.).
46	pub const WriteTargetWriter = struct {
47	    target: WriteTarget,
48	    io_writer: std.Io.Writer,
49	
50	    const io_vtable: std.Io.Writer.VTable = .{
51	        .drain = drain,
52	        .flush = std.Io.Writer.noopFlush,
53	        .rebase = std.Io.Writer.failingRebase,
54	    };
55	
56	    pub fn init(target: WriteTarget) WriteTargetWriter {
57	        return .{
58	            .target = target,
59	            .io_writer = .{
60	                .buffer = &.{},
61	                .vtable = &io_vtable,
62	            },
63	        };
64	    }
65	
66	    pub fn writer(self: *WriteTargetWriter) *std.Io.Writer {
67	        return &self.io_writer;
68	    }
69	
70	    /// Flush is a no-op — WriteTarget.write() is unbuffered (no partial writes).
71	    pub fn flush(_: *WriteTargetWriter) WriteError!void {}
72	
73	    fn drain(w: *std.Io.Writer, data: []const []const u8, splat: usize) std.Io.Writer.Error!usize {
74	        const self: *WriteTargetWriter = @fieldParentPtr("io_writer", w);
75	        var total: usize = 0;
76	        for (data[0 .. data.len - 1]) |bytes| {
77	            self.target.write(bytes) catch return error.WriteFailed;
78	            total += bytes.len;
79	        }
80	        const pattern = data[data.len - 1];
81	        for (0..splat) |_| {
82	            self.target.write(pattern) catch return error.WriteFailed;
83	            total += pattern.len;
84	        }
85	        return total;
86	    }
87	};
88

1	//! Parquet Writer
2	//!
3	//! High-level API for writing Parquet files.
4	//!
5	//! ## Example
6	//! ```zig
7	//! const parquet = @import("parquet");
8	//!
