91	    /// Count total physical columns across all ColumnDefs
92	    fn countPhysicalColumns(columns: []const ColumnDef) usize {
93	        var count: usize = 0;
94	        for (columns) |col| {
95	            if (col.schema_node) |node| {
96	                // Use SchemaNode's leaf counting for complex nested types
97	                count += node.countLeafColumns();
98	            } else if (col.is_struct) {
99	                count += if (col.struct_fields) |fields| fields.len else 0;
100	            } else if (col.is_map) {
101	                count += 2; // Map has 2 physical columns: key and value
102	            } else if (col.is_list) {
103	                count += 1; // List is one physical column
104	            } else {
105	                count += 1;
106	            }
107	        }
108	        return count;
109	    }
