111	    /// Initialize geospatial statistics builders for geometry/geography columns
112	    fn initGeoStatsBuilders(
113	        allocator: std.mem.Allocator,
114	        columns: []const ColumnDef,
115	        builders: *std.AutoHashMapUnmanaged(usize, *statistics.GeospatialStatisticsBuilder),
116	    ) !void {
117	        errdefer {
118	            var it = builders.iterator();
119	            while (it.next()) |entry| {
120	                entry.value_ptr.*.deinit();
121	                allocator.destroy(entry.value_ptr.*);
122	            }
123	            builders.deinit(allocator);
124	        }
125	        for (columns, 0..) |col, idx| {
126	            if (col.logical_type) |lt| {
127	                switch (lt) {
128	                    .geometry, .geography => {
129	                        const builder = try allocator.create(statistics.GeospatialStatisticsBuilder);
130	                        errdefer allocator.destroy(builder);
131	                        builder.* = statistics.GeospatialStatisticsBuilder.init(allocator);
132	                        try builders.put(allocator, idx, builder);
133	                    },
134	                    else => {},
135	                }
136	            }
137	        }
138	    }
