174	    /// Initialize a writer with a WriteTarget. The caller manages target lifetime
175	    /// unless _backend_cleanup is set (by convenience constructors in api/zig/).
176	    pub fn initWithTarget(
177	        allocator: std.mem.Allocator,
178	        target: WriteTarget,
179	        columns: []const ColumnDef,
180	    ) WriterError!Self {
181	        target.write(format.PARQUET_MAGIC) catch return error.WriteError;
182	
183	        const num_physical = countPhysicalColumns(columns);
184	
185	        const columns_written = allocator.alloc(bool, num_physical) catch return error.OutOfMemory;
186	        errdefer allocator.free(columns_written);
187	        @memset(columns_written, false);
188	
189	        const column_chunks = allocator.alloc(?format.ColumnChunk, num_physical) catch return error.OutOfMemory;
190	        errdefer allocator.free(column_chunks);
191	        @memset(column_chunks, null);
192	
193	        var geo_stats_builders: std.AutoHashMapUnmanaged(usize, *statistics.GeospatialStatisticsBuilder) = .empty;
194	        initGeoStatsBuilders(allocator, columns, &geo_stats_builders) catch return error.OutOfMemory;
195	
196	        return Self{
197	            .allocator = allocator,
198	            .target_writer = WriteTargetWriter.init(target),
199	            .columns = columns,
200	            .state = .initialized,
201	            .current_offset = 4,
202	            .num_rows = null,
203	            .num_physical_columns = num_physical,
204	            .columns_written = columns_written,
205	            .column_chunks = column_chunks,
206	            .geo_stats_builders = geo_stats_builders,
207	        };
208	    }
