218	    /// Clean up resources
219	    pub fn deinit(self: *Self) void {
220	        // Free column chunk metadata
221	        for (self.column_chunks) |*maybe_chunk| {
222	            if (maybe_chunk.*) |*chunk| {
223	                if (chunk.meta_data) |*md| {
224	                    self.allocator.free(md.encodings);
225	                    for (md.path_in_schema) |path| {
226	                        self.allocator.free(path);
227	                    }
228	                    self.allocator.free(md.path_in_schema);
229	                    // Free statistics if present
230	                    if (md.statistics) |stats| {
231	                        if (stats.min) |m| self.allocator.free(m);
232	                        if (stats.max) |m| self.allocator.free(m);
233	                        if (stats.min_value) |m| self.allocator.free(m);
234	                        if (stats.max_value) |m| self.allocator.free(m);
235	                    }
236	                    // Free geospatial statistics if present
237	                    if (md.geospatial_statistics) |geo_stats| {
238	                        if (geo_stats.geospatial_types) |gt| self.allocator.free(gt);
239	                    }
240	                }
241	            }
242	        }
243	        self.allocator.free(self.column_chunks);
244	        self.allocator.free(self.columns_written);
245	
246	        // Clean up geospatial statistics builders
247	        var iter = self.geo_stats_builders.iterator();
248	        while (iter.next()) |entry| {
249	            entry.value_ptr.*.deinit();
250	            self.allocator.destroy(entry.value_ptr.*);
251	        }
252	        self.geo_stats_builders.deinit(self.allocator);
253	
254	        if (self._backend_cleanup) |cleanup| {
255	            cleanup.deinit_fn(cleanup.ptr, self.allocator);
256	        }
257	    }
