1	//! Write Target Interface
2	//!
3	//! Provides a vtable-based interface for writing Parquet data to different backends.
4	//! This abstraction allows Writer and RowWriter to be backend-agnostic.
5	
6	const std = @import("std");
7	
8	/// Error type for write operations
9	pub const WriteError = error{
10	    WriteError,
11	    OutOfMemory,
12	    IntegerOverflow,
13	};
14	
15	/// Vtable-based interface for writing to different backends.
16	/// The Writer uses this interface to write Parquet data without knowing
17	/// the underlying storage mechanism.
18	pub const WriteTarget = struct {
19	    ptr: *anyopaque,
20	    vtable: *const VTable,
21	
22	    pub const VTable = struct {
23	        /// Write data to the target
24	        write: *const fn (ptr: *anyopaque, data: []const u8) WriteError!void,
25	        /// Close/finalize the target (flush buffers, complete uploads, etc.)
26	        close: *const fn (ptr: *anyopaque) WriteError!void,
27	    };
28	
29	    /// Write data to the target
30	    pub fn write(self: WriteTarget, data: []const u8) WriteError!void {
31	        return self.vtable.write(self.ptr, data);
32	    }
33	
34	    /// Close/finalize the target
35	    pub fn close(self: WriteTarget) WriteError!void {
36	        return self.vtable.close(self.ptr);
37	    }
38	};
39	
40	/// Adapter that bridges a `WriteTarget` vtable into a `*std.Io.Writer` interface.
41	///
42	/// Stores the `WriteTarget` and an unbuffered `std.Io.Writer` whose `drain`
43	/// forwards every write through `WriteTarget.write()`. This lets the column
44	/// writer pipeline (which requires `*std.Io.Writer`) work with any external
45	/// `WriteTarget` implementation (callbacks, custom sinks, etc.).
46	pub const WriteTargetWriter = struct {
47	    target: WriteTarget,
48	    io_writer: std.Io.Writer,
49	
50	    const io_vtable: std.Io.Writer.VTable = .{
51	        .drain = drain,
52	        .flush = std.Io.Writer.noopFlush,
53	        .rebase = std.Io.Writer.failingRebase,
54	    };
55	
56	    pub fn init(target: WriteTarget) WriteTargetWriter {
57	        return .{
58	            .target = target,
59	            .io_writer = .{
60	                .buffer = &.{},
61	                .vtable = &io_vtable,
62	            },
63	        };
64	    }
65	
66	    pub fn writer(self: *WriteTargetWriter) *std.Io.Writer {
67	        return &self.io_writer;
68	    }
69	
70	    /// Flush is a no-op — WriteTarget.write() is unbuffered (no partial writes).
71	    pub fn flush(_: *WriteTargetWriter) WriteError!void {}
72	
73	    fn drain(w: *std.Io.Writer, data: []const []const u8, splat: usize) std.Io.Writer.Error!usize {
74	        const self: *WriteTargetWriter = @fieldParentPtr("io_writer", w);
75	        var total: usize = 0;
76	        for (data[0 .. data.len - 1]) |bytes| {
77	            self.target.write(bytes) catch return error.WriteFailed;
78	            total += bytes.len;
79	        }
80	        const pattern = data[data.len - 1];
81	        for (0..splat) |_| {
82	            self.target.write(pattern) catch return error.WriteFailed;
83	            total += pattern.len;
84	        }
85	        return total;
86	    }
87	};
