405	            switch (lt) {
406	                .geometry, .geography => {
407	                    if (result.metadata.statistics) |*stats| {
408	                        // Free min/max memory but keep null_count
409	                        if (stats.min) |m| self.allocator.free(m);
410	                        if (stats.max) |m| self.allocator.free(m);
411	                        if (stats.min_value) |m| self.allocator.free(m);
412	                        if (stats.max_value) |m| self.allocator.free(m);
413	                        stats.min = null;
