528	    /// Write a struct field
529	    /// Supports: i32, i64, []const u8
530	    /// parent_nulls indicates which rows have a null parent struct
531	    pub fn writeStructField(
532	        self: *Self,
533	        comptime T: type,
534	        struct_col_index: usize,
535	        field_index: usize,
536	        values: []const ?T,
537	        parent_nulls: []const bool,
538	    ) WriterError!void {
539	        const physical_type = comptime physicalTypeFor(T);
540	        try self.validateStructFieldWrite(struct_col_index, field_index, physical_type);
541	        const physical_idx = try self.getPhysicalColumnIndex(struct_col_index, field_index);
542	
543	        const col_def = self.columns[struct_col_index];
544	        const fields = col_def.struct_fields orelse return error.InvalidColumnIndex;
545	        const field = fields[field_index];
546	
547	        // Compute definition levels:
548	        // def=0: parent struct is null
549	        // def=1: parent present, but field is null
550	        // def=2: field is present
551	        const max_def_level: u8 = 2;
552	        const def_levels = self.allocator.alloc(u32, values.len) catch return error.OutOfMemory;
553	        defer self.allocator.free(def_levels);
554	
555	        var actual_values: std.ArrayList(T) = .empty;
556	        defer actual_values.deinit(self.allocator);
557	
558	        for (values, parent_nulls, 0..) |maybe_val, parent_null, i| {
559	            if (parent_null) {
560	                def_levels[i] = 0;
561	            } else if (maybe_val) |val| {
562	                def_levels[i] = 2;
563	                actual_values.append(self.allocator, val) catch return error.OutOfMemory;
564	            } else {
565	                def_levels[i] = 1;
566	            }
567	        }
568	
569	        // All rep levels are 0 for struct fields
570	        const rep_levels = self.allocator.alloc(u32, values.len) catch return error.OutOfMemory;
571	        defer self.allocator.free(rep_levels);
572	        @memset(rep_levels, 0);
573	
574	        const writer = self.getWriter();
575	        var result = if (T == []const u8)
576	            column_writer.writeColumnChunkStructByteArray(
577	                self.allocator,
578	                writer,
579	                col_def.name,
580	                field.name,
581	                actual_values.items,
582	                def_levels,
583	                rep_levels,
584	                max_def_level,
585	                self.current_offset,
586	                col_def.codec,
587	            ) catch |e| return mapColumnError(e)
588	        else
589	            column_writer.writeColumnChunkStruct(
590	                T,
591	                self.allocator,
592	                writer,
593	                col_def.name,
594	                field.name,
595	                actual_values.items,
596	                def_levels,
597	                rep_levels,
598	                max_def_level,
599	                self.current_offset,
600	                col_def.codec,
601	            ) catch |e| return mapColumnError(e);
602	
603	        try self.flushWriter();
604	        try self.recordColumnWrite(physical_idx, &result, values.len);
605	    }
