630	    /// Write a map column with the given key and value types.
631	    /// Supported types: i32, i64, f32, f64, bool, []const u8.
632	    pub fn writeMapColumn(
633	        self: *Self,
634	        comptime K: type,
635	        comptime V: type,
636	        column_index: usize,
637	        maps: []const Optional([]const MapEntry(K, V)),
638	    ) WriterError!void {
639	        const key_pt = comptime zigTypeToPhysicalType(K);
640	        const value_pt = comptime zigTypeToPhysicalType(V);
641	        try self.validateMapColumnWrite(column_index, key_pt, value_pt);
642	        const key_physical_idx = try self.getPhysicalColumnIndex(column_index, 0);
643	        const value_physical_idx = try self.getPhysicalColumnIndex(column_index, 1);
644	
645	        const col_def = self.columns[column_index];
646	        const writer = self.getWriter();
647	
648	        var flattened = map_encoder.flattenMap(
649	            K,
650	            V,
651	            self.allocator,
652	            maps,
653	            3,
654	        ) catch return error.OutOfMemory;
655	        defer flattened.deinit();
656	
657	        const key_result = column_writer.writeColumnChunkMapKey(
658	            self.allocator,
659	            writer,
660	            col_def.name,
661	            K,
662	            flattened.keys,
663	            flattened.key_def_levels,
664	            flattened.rep_levels,
665	            2,
666	            1,
667	            self.current_offset,
668	            col_def.codec,
669	        ) catch |e| return mapColumnError(e);
670	
671	        try self.flushWriter();
672	        self.columns_written[key_physical_idx] = true;
673	        self.current_offset = std.math.add(i64, self.current_offset, try safe.castTo(i64, key_result.total_bytes)) catch return error.IntegerOverflow;
674	        self.column_chunks[key_physical_idx] = .{
675	            .file_path = null,
676	            .file_offset = key_result.file_offset,
677	            .meta_data = key_result.metadata,
678	        };
679	
680	        const value_result = column_writer.writeColumnChunkMapValue(
681	            self.allocator,
682	            writer,
683	            col_def.name,
684	            V,
685	            flattened.values,
686	            flattened.value_def_levels,
687	            flattened.rep_levels,
688	            3,
689	            1,
690	            self.current_offset,
691	            col_def.codec,
692	        ) catch |e| return mapColumnError(e);
693	
694	        try self.flushWriter();
695	        self.columns_written[value_physical_idx] = true;
696	        self.current_offset = std.math.add(i64, self.current_offset, try safe.castTo(i64, value_result.total_bytes)) catch return error.IntegerOverflow;
697	        self.column_chunks[value_physical_idx] = .{
698	            .file_path = null,
699	            .file_offset = value_result.file_offset,
700	            .meta_data = value_result.metadata,
701	        };
702	
703	        if (self.num_rows) |existing| {
704	            if (existing != (safe.castTo(i64, maps.len) catch return error.RowCountMismatch)) {
705	                return error.RowCountMismatch;
706	            }
707	        } else {
708	            if (maps.len > std.math.maxInt(i64)) return error.TooManyRows;
709	            self.num_rows = try safe.castTo(i64, maps.len);
710	        }
711	
712	        self.state = .writing_columns;
713	    }
