735	    /// Write a column using the Value type for nested data.
736	    /// This method uses the SchemaNode defined in the ColumnDef to flatten
737	    /// the nested Value data and write it to the appropriate physical columns.
738	    ///
739	    /// Example:
740	    /// ```zig
741	    /// // Define schema: list<struct<id: i64, name: string>>
742	    /// const id_node = SchemaNode{ .int64 = .{} };
743	    /// const name_node = SchemaNode{ .byte_array = .{} };
744	    /// const struct_node = SchemaNode{ .struct_ = .{ .fields = &.{
745	    ///     .{ .name = "id", .node = &id_node },
746	    ///     .{ .name = "name", .node = &name_node },
747	    /// }}};
748	    /// const list_node = SchemaNode{ .list = &struct_node };
749	    ///
750	    /// const columns = [_]ColumnDef{ColumnDef.fromNode("items", &list_node)};
751	    /// var writer = try Writer.init(allocator, file, &columns);
752	    ///
753	    /// // Write data as Value
754	    /// const row_values = [_]Value{...};  // Array of list values, one per row
755	    /// try writer.writeNestedColumn(0, &row_values);
756	    /// ```
757	    pub fn writeNestedColumn(
758	        self: *Self,
759	        column_index: usize,
760	        rows: []const Value,
761	    ) WriterError!void {
762	        if (self.state == .closed) return error.InvalidState;
763	        if (column_index >= self.columns.len) return error.InvalidColumnIndex;
764	
765	        const col_def = self.columns[column_index];
766	        const node = col_def.schema_node orelse return error.TypeMismatch;
767	
768	        // Flatten each row and combine
769	        var all_columns: std.ArrayList(nested_mod.FlatColumn) = .empty;
770	        defer {
771	            for (all_columns.items) |*col| {
772	                col.deinit(self.allocator);
773	            }
774	            all_columns.deinit(self.allocator);
775	        }
776	
777	        const leaf_count = node.countLeafColumns();
778	
779	        // Initialize columns for accumulating all rows
780	        for (0..leaf_count) |_| {
781	            all_columns.append(self.allocator, nested_mod.FlatColumn.init()) catch return error.OutOfMemory;
782	        }
783	
784	        // Flatten each row and append to columns
785	        for (rows) |row_value| {
786	            var row_columns = nested_mod.flattenValue(self.allocator, node, row_value) catch return error.OutOfMemory;
787	            defer row_columns.deinit();
788	
789	            for (row_columns.columns.items, 0..) |col, i| {
790	                for (col.values.items) |v| {
791	                    all_columns.items[i].values.append(self.allocator, v) catch return error.OutOfMemory;
792	                }
793	                for (col.def_levels.items) |d| {
794	                    all_columns.items[i].def_levels.append(self.allocator, d) catch return error.OutOfMemory;
795	                }
796	                for (col.rep_levels.items) |r| {
797	                    all_columns.items[i].rep_levels.append(self.allocator, r) catch return error.OutOfMemory;
798	                }
799	            }

400	        }
401	
402	        // GEOMETRY/GEOGRAPHY types: skip min/max statistics (sort order undefined)
403	        // but keep null_count, and update bbox tracking
404	        if (col_def.logical_type) |lt| {
405	            switch (lt) {
406	                .geometry, .geography => {
407	                    if (result.metadata.statistics) |*stats| {
408	                        // Free min/max memory but keep null_count
409	                        if (stats.min) |m| self.allocator.free(m);
410	                        if (stats.max) |m| self.allocator.free(m);
411	                        if (stats.min_value) |m| self.allocator.free(m);
412	                        if (stats.max_value) |m| self.allocator.free(m);
413	                        stats.min = null;
414	                        stats.max = null;
415	                        stats.min_value = null;
416	                        stats.max_value = null;
417	                    }
418	                    // Update geospatial statistics builder for bbox tracking
419	                    if (self.geo_stats_builders.get(column_index)) |builder| {
420	                        builder.updateOptional(values);
421	                    }
422	                },
423	                else => {},
424	            }
425	        }
426	
427	        try self.flushWriter();
428	        try self.recordColumnWrite(physical_idx, &result, values.len);
429	    }
