792	                }
793	                for (col.def_levels.items) |d| {
794	                    all_columns.items[i].def_levels.append(self.allocator, d) catch return error.OutOfMemory;
795	                }
796	                for (col.rep_levels.items) |r| {
797	                    all_columns.items[i].rep_levels.append(self.allocator, r) catch return error.OutOfMemory;
