120	pub fn writeColumnChunkDictOptionalWithPathArray(
121	    comptime T: type,
122	    allocator: std.mem.Allocator,
123	    output: *std.Io.Writer,
124	    path_in_schema: []const []const u8,
125	    values: []const Optional(T),
126	    is_optional: bool,
127	    start_offset: i64,
128	    codec: format.CompressionCodec,
129	    dictionary_size_limit: ?usize,
130	    dictionary_cardinality_threshold: ?f32,
131	    max_page_size: ?usize,
132	    write_page_checksum: bool,
133	) ColumnWriteError!ColumnChunkResult {
134	    if (values.len == 0) {
135	        // Fall back to plain encoding for empty columns
136	        return writeColumnChunkOptionalWithPathArray(T, allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
137	    }
138	
139	    // Compute statistics using unified API
140	    var stats_builder = statistics.StatisticsBuilder(T){};
141	    stats_builder.updateOptional(values);
142	    var stats = stats_builder.build(allocator) catch return error.OutOfMemory;
143	    errdefer if (stats) |s| freeStatistics(allocator, s);
144	
145	    // Build dictionary from non-null values
146	    var unique_map = std.HashMap(T, u32, DictHashContext(T), std.hash_map.default_max_load_percentage).init(allocator);
147	    defer unique_map.deinit();
148	    var dict_values: std.ArrayListUnmanaged(T) = .empty;
149	    defer dict_values.deinit(allocator);
150	
151	    var non_null_count: usize = 0;
152	    for (values) |v| {
153	        if (v != .null_value) non_null_count += 1;
154	    }
155	
156	    var indices = allocator.alloc(u32, non_null_count) catch return error.OutOfMemory;
157	    defer allocator.free(indices);
158	
159	    var idx: usize = 0;
160	    for (values) |v| {
161	        if (v != .null_value) {
162	            const val = v.value;
163	            if (unique_map.get(val)) |dict_idx| {
164	                indices[idx] = dict_idx;
165	            } else {
166	                const new_idx: u32 = try safe.castTo(u32, dict_values.items.len);
167	                unique_map.put(val, new_idx) catch return error.OutOfMemory;
168	                dict_values.append(allocator, val) catch return error.OutOfMemory;
169	                indices[idx] = new_idx;
170	            }
171	            idx += 1;
172	
173	            // Check cardinality threshold early abort
174	            if (dictionary_cardinality_threshold) |threshold| {
175	                if (idx >= 1024) {
176	                    const ratio = @as(f32, @floatFromInt(dict_values.items.len)) / @as(f32, @floatFromInt(idx));
177	                    if (ratio > threshold) {
178	                        if (stats) |s| freeStatistics(allocator, s);
179	                        stats = null;
180	                        return writeColumnChunkOptionalWithPathArray(T, allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
181	                    }
182	                }
183	            }
184	        }
185	    }
186	
187	    const dict_size = dict_values.items.len;
188	
189	    // Check dictionary size limit
190	    const dict_bytes = dict_size * @sizeOf(T);
191	    if (dictionary_size_limit) |limit| {
192	        if (dict_bytes > limit) {
193	            if (stats) |s| freeStatistics(allocator, s);
194	            stats = null;
195	            return writeColumnChunkOptionalWithPathArray(T, allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
196	        }
197	    }
198	
199	    // Write dictionary page (PLAIN encoded)
200	    const bytes_per_value = @sizeOf(T);
201	    const dict_data = allocator.alloc(u8, dict_size * bytes_per_value) catch return error.OutOfMemory;
202	    defer allocator.free(dict_data);
203	
204	    for (dict_values.items, 0..) |v, i| {
205	        if (T == i32) {
206	            std.mem.writeInt(i32, dict_data[i * 4 ..][0..4], v, .little);
207	        } else if (T == i64) {
208	            std.mem.writeInt(i64, dict_data[i * 8 ..][0..8], v, .little);
209	        } else if (T == f32) {
210	            std.mem.writeInt(u32, dict_data[i * 4 ..][0..4], @bitCast(v), .little);
211	        } else if (T == f64) {
212	            std.mem.writeInt(u64, dict_data[i * 8 ..][0..8], @bitCast(v), .little);
213	        }
214	    }
215	
216	    // Compress dictionary data if needed
217	    const dict_compressed: []const u8 = if (codec == .uncompressed)
218	        dict_data
219	    else blk: {
220	        break :blk compress.compress(allocator, dict_data, codec) catch |err| switch (err) {
221	            error.UnsupportedCompression => return error.UnsupportedCompression,
222	            error.CompressionError => return error.CompressionError,
223	            error.OutOfMemory => return error.OutOfMemory,
224	        };
225	    };
226	    defer if (codec != .uncompressed) allocator.free(dict_compressed);
227	
228	    // Write dictionary page header
229	    const dict_page_header = format.PageHeader{
230	        .type_ = .dictionary_page,
231	        .uncompressed_page_size = try safe.castTo(i32, dict_data.len),
232	        .compressed_page_size = try safe.castTo(i32, dict_compressed.len),
233	        .crc = if (write_page_checksum) computePageCrc(dict_compressed) else null,
234	        .data_page_header = null,
235	        .dictionary_page_header = .{
