242	    var dict_thrift = thrift.CompactWriter.init(allocator);
243	    defer dict_thrift.deinit();
244	    dict_page_header.serialize(&dict_thrift) catch return error.OutOfMemory;
245	    const dict_header_bytes = dict_thrift.getWritten();
246	
247	    output.writeAll(dict_header_bytes) catch return error.WriteError;
248	    output.writeAll(dict_compressed) catch return error.WriteError;
249	
250	    var total_bytes_written: usize = dict_header_bytes.len + dict_compressed.len;
251	    var total_uncompressed_written: usize = dict_header_bytes.len + dict_data.len;
252	    const dict_page_offset = start_offset;
253	    const data_page_offset = start_offset + try safe.castTo(i64, total_bytes_written);
