255	    // Compute bit width for indices
256	    const bit_width: u5 = if (dict_size <= 1) 0 else try safe.castTo(u5, std.math.log2_int(usize, dict_size - 1) + 1);
257	
258	    // Calculate values per page
259	    const values_per_page: usize = if (max_page_size) |max_size| blk: {
260	        const bytes_per_value_estimate: usize = 3;
261	        const usable_size = if (max_size > 20) max_size - 20 else max_size;
262	        const vpp = usable_size / bytes_per_value_estimate;
263	        break :blk if (vpp > 0) vpp else 1;
264	    } else values.len;
265	
266	    // Write data pages
267	    var value_offset: usize = 0;
268	    var index_offset: usize = 0;
269	
270	    while (value_offset < values.len) {
271	        const page_end = @min(value_offset + values_per_page, values.len);
272	        const page_values = values[value_offset..page_end];
273	
274	        // Count non-null values in this page
275	        var page_non_null_count: usize = 0;
276	        for (page_values) |v| {
277	            if (v != .null_value) page_non_null_count += 1;
278	        }
279	
280	        // Get indices for this page
281	        const page_indices = indices[index_offset .. index_offset + page_non_null_count];
282	        index_offset += page_non_null_count;
283	
284	        // Encode indices using RLE/bit-packed hybrid
285	        const rle_data = rle_encoder.encode(allocator, page_indices, bit_width) catch return error.OutOfMemory;
286	        defer allocator.free(rle_data);
287	
288	        // Optional columns always need definition levels, even when all values are non-null
289	        const data_page_uncompressed = if (is_optional) blk: {
290	            var page_def_levels = allocator.alloc(bool, page_values.len) catch return error.OutOfMemory;
291	            defer allocator.free(page_def_levels);
292	
293	            for (page_values, 0..) |v, i| {
294	                page_def_levels[i] = v != .null_value;
295	            }
296	
297	            const def_level_data = rle_encoder.encodeDefLevelsWithLength(allocator, page_def_levels) catch return error.OutOfMemory;
298	            defer allocator.free(def_level_data);
299	
300	            const page_data = allocator.alloc(u8, def_level_data.len + 1 + rle_data.len) catch return error.OutOfMemory;
301	            @memcpy(page_data[0..def_level_data.len], def_level_data);
302	            page_data[def_level_data.len] = bit_width;
303	            @memcpy(page_data[def_level_data.len + 1 ..], rle_data);
304	            break :blk page_data;
305	        } else blk: {
306	            const page_data = allocator.alloc(u8, 1 + rle_data.len) catch return error.OutOfMemory;
307	            page_data[0] = bit_width;
308	            @memcpy(page_data[1..], rle_data);
309	            break :blk page_data;
310	        };
311	        defer allocator.free(data_page_uncompressed);
312	
313	        // Compress data page if needed
314	        const data_compressed: []const u8 = if (codec == .uncompressed)
315	            data_page_uncompressed
316	        else cblk: {
317	            break :cblk compress.compress(allocator, data_page_uncompressed, codec) catch |err| switch (err) {
318	                error.UnsupportedCompression => return error.UnsupportedCompression,
319	                error.CompressionError => return error.CompressionError,
320	                error.OutOfMemory => return error.OutOfMemory,
321	            };
322	        };
323	        defer if (codec != .uncompressed) allocator.free(data_compressed);
324	
325	        // Write data page header
326	        const data_page_header = format.PageHeader{
327	            .type_ = .data_page,
328	            .uncompressed_page_size = try safe.castTo(i32, data_page_uncompressed.len),
329	            .compressed_page_size = try safe.castTo(i32, data_compressed.len),
330	            .crc = if (write_page_checksum) computePageCrc(data_compressed) else null,
331	            .data_page_header = .{
332	                .num_values = try safe.castTo(i32, page_values.len),
333	                .encoding = .rle_dictionary,
334	                .definition_level_encoding = .rle,
335	                .repetition_level_encoding = .rle,
336	                .statistics = null,
337	            },
338	            .dictionary_page_header = null,
339	        };
340	
341	        var data_thrift = thrift.CompactWriter.init(allocator);
342	        defer data_thrift.deinit();
343	        data_page_header.serialize(&data_thrift) catch return error.OutOfMemory;
344	        const data_header_bytes = data_thrift.getWritten();
345	
346	        output.writeAll(data_header_bytes) catch return error.WriteError;
347	        output.writeAll(data_compressed) catch return error.WriteError;
348	
349	        const page_bytes = std.math.add(usize, data_header_bytes.len, data_compressed.len) catch return error.IntegerOverflow;
350	        total_bytes_written = std.math.add(usize, total_bytes_written, page_bytes) catch return error.IntegerOverflow;
351	        const uncompressed_page_bytes = std.math.add(usize, data_header_bytes.len, data_page_uncompressed.len) catch return error.IntegerOverflow;
352	        total_uncompressed_written = std.math.add(usize, total_uncompressed_written, uncompressed_page_bytes) catch return error.IntegerOverflow;
353	        value_offset = page_end;
354	    }
355	
356	    // Build metadata (integer dict function)
357	    const path = allocator.alloc([]const u8, path_in_schema.len) catch return error.OutOfMemory;
358	    for (path_in_schema, 0..) |segment, i| {
359	        path[i] = allocator.dupe(u8, segment) catch return error.OutOfMemory;
360	    }
361	
362	    const encodings = allocator.alloc(format.Encoding, 3) catch return error.OutOfMemory;
363	    encodings[0] = .plain; // Dictionary page
364	    encodings[1] = .rle; // Definition levels
365	    encodings[2] = .rle_dictionary; // Data page
366	
367	    return .{
368	        .metadata = .{
369	            .type_ = comptime typeToPhysicalType(T),
370	            .encodings = encodings,
371	            .path_in_schema = path,
372	            .codec = codec,
373	            .num_values = try safe.castTo(i64, values.len),
374	            .total_uncompressed_size = try safe.castTo(i64, total_uncompressed_written),
375	            .total_compressed_size = try safe.castTo(i64, total_bytes_written),
376	            .data_page_offset = data_page_offset,
377	            .index_page_offset = null,
378	            .dictionary_page_offset = dict_page_offset,
379	            .statistics = stats,
380	        },
381	        .file_offset = start_offset,
382	        .total_bytes = total_bytes_written,
383	    };
