783	/// Write a byte array data page with Optional values and a specific encoding.
784	/// Unified function for byte arrays (Phase 11 style).
785	/// Definition levels are written based on is_optional (schema), not data content.
786	pub fn writeDataPageByteArrayOptionalWithEncoding(
787	    allocator: std.mem.Allocator,
788	    values: []const Optional([]const u8),
789	    is_optional: bool,
790	    encoding: format.Encoding,
791	) PageWriteError!DataPageResult {
792	    var non_null_values: std.ArrayList([]const u8) = .empty;
793	    defer non_null_values.deinit(allocator);
794	
795	    var is_defined: std.ArrayList(bool) = .empty;
796	    defer is_defined.deinit(allocator);
797	
798	    for (values) |v| {
799	        const defined = v != .null_value;
800	        try is_defined.append(allocator, defined);
801	        if (defined) {
802	            try non_null_values.append(allocator, v.value);
803	        }
804	    }
805	
806	    if (!is_optional and non_null_values.items.len != values.len) return error.NullInRequiredColumn;
807	
808	    // Encode the non-null values with specified encoding
809	    const encoded_values = try encodeByteArraysWithEncoding(allocator, non_null_values.items, encoding);
810	    defer allocator.free(encoded_values);
811	
812	    if (!is_optional) {
813	        const result = try allocator.dupe(u8, encoded_values);
814	        return .{
815	            .data = result,
816	            .num_values = values.len,
817	            .num_non_null = values.len,
818	        };
819	    }

130	    return combineDefLevelsAndValues(allocator, def_levels, encoded_values, total_values);
131	}
