133	/// Combine definition levels and values into a data page
134	fn combineDefLevelsAndValues(
135	    allocator: std.mem.Allocator,
136	    is_defined: []const bool,
137	    encoded_values: []const u8,
138	    total_values: usize,
139	) PageWriteError!DataPageResult {
140	    // Encode definition levels with length prefix
141	    const def_level_data = try rle_encoder.encodeDefLevelsWithLength(allocator, is_defined);
142	    defer allocator.free(def_level_data);
143	
144	    // Count non-null values
145	    var num_non_null: usize = 0;
146	    for (is_defined) |d| {
147	        if (d) num_non_null += 1;
148	    }
149	
150	    // Combine: def levels + values
151	    const total_size = def_level_data.len + encoded_values.len;
152	    const result = try allocator.alloc(u8, total_size);
153	
154	    @memcpy(result[0..def_level_data.len], def_level_data);
155	    @memcpy(result[def_level_data.len..], encoded_values);
156	
157	    return .{
158	        .data = result,
159	        .num_values = total_values,
160	        .num_non_null = num_non_null,
161	    };
162	}
