1	//! RLE/Bit-Packed Hybrid Encoder
2	//!
3	//! This encoding is used for:
4	//! - Definition levels
5	//! - Repetition levels
6	//! - Dictionary indices
7	//!
8	//! The encoding uses RLE for runs of repeated values and bit-packing for mixed values.
9	//! This is the inverse of rle.zig's decode function.
10	//!
11	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#rle
12	
13	const std = @import("std");
14	const safe = @import("../safe.zig");
15	
16	/// Encode values using RLE/bit-packed hybrid encoding
17	/// For simplicity, we primarily use RLE runs since definition levels often repeat.
18	pub fn encode(allocator: std.mem.Allocator, values: []const u32, bit_width: u5) ![]u8 {
19	    if (values.len == 0) {
20	        return try allocator.alloc(u8, 0);
21	    }
22	
23	    if (bit_width == 0) {
24	        // All values must be 0, encode as empty
25	        return try allocator.alloc(u8, 0);
26	    }
27	
28	    var buffer: std.ArrayList(u8) = .empty;
29	    errdefer buffer.deinit(allocator);
30	
31	    var i: usize = 0;
32	    while (i < values.len) {
33	        // Count consecutive equal values (RLE run)
34	        var run_len: usize = 1;
35	        while (i + run_len < values.len and values[i + run_len] == values[i] and run_len < 0x7FFFFFFF) {
36	            run_len += 1;
37	        }
38	
39	        // Use RLE if we have at least 8 values (threshold for efficiency)
40	        // or if it's the last run
41	        if (run_len >= 8 or i + run_len == values.len) {
42	            // Encode as RLE run
43	            try encodeRleRun(&buffer, allocator, values[i], run_len, bit_width);
44	            i += run_len;
45	        } else {
46	            // Encode as bit-packed run (groups of 8)
47	            // Find how many values until the next good RLE opportunity
48	            var pack_count: usize = 0;
49	            var j = i;
50	            while (j < values.len) {
51	                var next_run: usize = 1;
52	                while (j + next_run < values.len and values[j + next_run] == values[j]) {
53	                    next_run += 1;
54	                }
55	                if (next_run >= 8) break;
56	                pack_count += next_run;
57	                j += next_run;
58	            }
59	
60	            // Round up to multiple of 8
61	            pack_count = @min(pack_count, values.len - i);
62	            const groups = (pack_count + 7) / 8;
63	            const actual_count = groups * 8;
64	
65	            try encodeBitPackedRun(&buffer, allocator, values[i..], @min(actual_count, values.len - i), bit_width);
66	            i += @min(actual_count, values.len - i);
67	        }
68	    }
69	
70	    const result = try buffer.toOwnedSlice(allocator);
71	    return result;
72	}
73	
74	/// Encode an RLE run: (count << 1 | 0) followed by value bytes
75	fn encodeRleRun(buffer: *std.ArrayList(u8), allocator: std.mem.Allocator, value: u32, count: usize, bit_width: u5) !void {
76	    // Write indicator: count << 1 (RLE flag is 0)
77	    const indicator = count << 1;
78	    try writeVarInt(buffer, allocator, indicator);
79	
80	    // Write value using ceil(bit_width / 8) bytes
81	    const value_bytes = (@as(usize, bit_width) + 7) / 8;
82	    var v = value;
83	    for (0..value_bytes) |_| {
84	        try buffer.append(allocator, @truncate(v));
85	        v >>= 8;
86	    }
87	}
88	
89	/// Encode a bit-packed run: (num_groups << 1 | 1) followed by packed bytes
90	fn encodeBitPackedRun(buffer: *std.ArrayList(u8), allocator: std.mem.Allocator, values: []const u32, count: usize, bit_width: u5) !void {
91	    // Number of groups of 8 values
92	    const num_groups = (count + 7) / 8;
93	
94	    // Write indicator: num_groups << 1 | 1 (bit-packed flag)
95	    const indicator = (num_groups << 1) | 1;
96	    try writeVarInt(buffer, allocator, indicator);
97	
98	    // Pack values into bytes
99	    const total_bits = num_groups * 8 * @as(usize, bit_width);
100	    const total_bytes = (total_bits + 7) / 8;
101	
102	    const start_pos = buffer.items.len;
103	    try buffer.appendNTimes(allocator, 0, total_bytes);
104	
105	    var bit_pos: usize = 0;
106	    for (0..count) |i| {
107	        const value = if (i < values.len) values[i] else 0;
108	        try writeBits(buffer.items[start_pos..], bit_pos, value, bit_width);
109	        bit_pos += bit_width;
110	    }
111	
112	    // Pad remaining values in last group with 0
113	    const remainder = count % 8;
114	    if (remainder != 0) {
115	        for (remainder..8) |_| {
116	            // Already 0 from appendNTimes
117	            bit_pos += bit_width;
118	        }
119	    }
120	}
121	
122	/// Write a value using bit_width bits starting at bit_pos
123	fn writeBits(bytes: []u8, bit_pos: usize, value: u32, bit_width: u5) !void {
124	    if (bit_width == 0) return;
125	
126	    var remaining_bits: u5 = bit_width;
127	    var current_bit = bit_pos;
128	    var v = value;
129	
130	    while (remaining_bits > 0) {
131	        const byte_idx = current_bit / 8;
132	        const bit_offset: u3 = safe.castTo(u3, current_bit % 8) catch unreachable; // % 8 guarantees it fits in u3
133	        const bits_in_byte: u4 = safe.castTo(u4, @min(8 - @as(u4, bit_offset), remaining_bits)) catch unreachable; // @min of values <= 8 fits in u4 (max 15)
134	
135	        if (byte_idx >= bytes.len) return;
136	
137	        // bits_in_byte is <= 8, so the shift and mask are well within u16/u8 limits
138	        const mask: u8 = safe.castTo(u8, (@as(u16, 1) << bits_in_byte) - 1) catch unreachable; // bits_in_byte <= 8, so (1 << bits_in_byte) - 1 <= 255
139	        bytes[byte_idx] |= @as(u8, @truncate(v & mask)) << bit_offset;
140	
141	        v >>= safe.castTo(u5, bits_in_byte) catch unreachable; // bits_in_byte is <= 8
142	        current_bit += bits_in_byte;
143	        remaining_bits -= safe.castTo(u5, bits_in_byte) catch unreachable; // bits_in_byte is <= 8, fits in u5
144	    }
145	}
146	
147	/// Write a varint to the buffer
148	fn writeVarInt(buffer: *std.ArrayList(u8), allocator: std.mem.Allocator, value: usize) !void {
149	    var v = value;
150	    while (v >= 0x80) {
151	        try buffer.append(allocator, @as(u8, @truncate(v)) | 0x80);
152	        v >>= 7;
153	    }
154	    try buffer.append(allocator, @truncate(v));
155	}
