157	/// Encode definition levels from a bool array (true = present, false = null)
158	/// This is a convenience wrapper for flat schemas where max_def_level = 1.
159	fn encodeDefLevels(allocator: std.mem.Allocator, is_defined: []const bool) ![]u8 {
160	    // Convert bools to u32s (0 or 1)
161	    const values = try allocator.alloc(u32, is_defined.len);
162	    defer allocator.free(values);
163	
164	    for (is_defined, 0..) |defined, i| {
165	        values[i] = if (defined) 1 else 0;
166	    }
167	
168	    // Encode with bit_width 1
169	    return encode(allocator, values, 1);
170	}
