172	/// Encode levels (definition or repetition) with a specified max level.
173	/// For nested types, max_level can be > 1.
174	/// The bit width is computed from max_level.
175	fn encodeLevels(allocator: std.mem.Allocator, levels: []const u32, max_level: u8) ![]u8 {
176	    const bit_width = computeBitWidth(max_level);
177	    return encode(allocator, levels, bit_width);
178	}
