180	/// Encode levels with a 4-byte length prefix (for V1 data pages)
181	pub fn encodeLevelsWithLength(allocator: std.mem.Allocator, levels: []const u32, max_level: u8) ![]u8 {
182	    const encoded = try encodeLevels(allocator, levels, max_level);
183	    defer allocator.free(encoded);
184	
185	    const total = std.math.add(usize, 4, encoded.len) catch return error.OutOfMemory;
186	    const result = try allocator.alloc(u8, total);
187	    std.mem.writeInt(u32, result[0..4], try safe.castTo(u32, encoded.len), .little);
188	    @memcpy(result[4..], encoded);
189	
190	    return result;
191	}
192	
193	/// Compute the bit width needed to encode values up to max_level
194	fn computeBitWidth(max_level: u8) u5 {
195	    if (max_level == 0) return 0;
196	    // log2_int(max_level) for max_level=255 is 7. +1 is 8. Safely fits in u5.
197	    return safe.castTo(u5, std.math.log2_int(u8, max_level) + 1) catch unreachable; // max_level is u8, so log2 + 1 <= 8, fits u5
198	}
199	
200	/// Encode definition levels with a 4-byte length prefix (for V1 data pages)
201	pub fn encodeDefLevelsWithLength(allocator: std.mem.Allocator, is_defined: []const bool) ![]u8 {
202	    const encoded = try encodeDefLevels(allocator, is_defined);
203	    defer allocator.free(encoded);
204	
205	    const total = std.math.add(usize, 4, encoded.len) catch return error.OutOfMemory;
206	    const result = try allocator.alloc(u8, total);
207	    std.mem.writeInt(u32, result[0..4], try safe.castTo(u32, encoded.len), .little);
208	    @memcpy(result[4..], encoded);
209	
210	    return result;
211	}
