213	/// Encode boolean values using RLE/bit-packed hybrid encoding.
214	/// This is more efficient than PLAIN bit-packing for data with runs of same values.
215	pub fn encodeBooleans(allocator: std.mem.Allocator, values: []const bool) ![]u8 {
216	    // Convert bools to u32s (0 or 1)
217	    const u32_values = try allocator.alloc(u32, values.len);
218	    defer allocator.free(u32_values);
219	
220	    for (values, 0..) |v, i| {
221	        u32_values[i] = if (v) 1 else 0;
222	    }
223	
224	    // Encode with bit_width 1
225	    return encode(allocator, u32_values, 1);
226	}
