1	//! PLAIN encoding encoder
2	//!
3	//! PLAIN is the simplest encoding in Parquet:
4	//! - Boolean: 1 bit per value, packed into bytes (LSB first)
5	//! - Int32/Int64: 4/8 bytes little-endian
6	//! - Float/Double: 4/8 bytes IEEE 754 little-endian
7	//! - ByteArray: 4-byte length prefix + bytes
8	//! - FixedLenByteArray: just the bytes (length known from schema)
9	
10	const std = @import("std");
11	const safe = @import("../safe.zig");
12	
13	/// Encode booleans as bit-packed bytes (LSB first)
14	pub fn encodeBooleans(allocator: std.mem.Allocator, values: []const bool) ![]u8 {
15	    const num_bytes = (values.len + 7) / 8;
16	    const result = try allocator.alloc(u8, num_bytes);
17	    @memset(result, 0);
18	
19	    for (values, 0..) |value, i| {
20	        if (value) {
21	            const byte_idx = i / 8;
22	            const bit_idx: u3 = safe.castTo(u3, i % 8) catch unreachable; // i % 8 is strictly 0-7
23	            result[byte_idx] |= @as(u8, 1) << bit_idx;
24	        }
25	    }
26	
27	    return result;
28	}
29	
30	/// Encode i32 values as little-endian 4-byte integers
31	pub fn encodeInt32(allocator: std.mem.Allocator, values: []const i32) ![]u8 {
32	    const result = try allocator.alloc(u8, values.len * 4);
33	
34	    for (values, 0..) |value, i| {
35	        std.mem.writeInt(i32, result[i * 4 ..][0..4], value, .little);
36	    }
37	
38	    return result;
39	}
40	
41	/// Encode i64 values as little-endian 8-byte integers
42	pub fn encodeInt64(allocator: std.mem.Allocator, values: []const i64) ![]u8 {
43	    const result = try allocator.alloc(u8, values.len * 8);
44	
45	    for (values, 0..) |value, i| {
46	        std.mem.writeInt(i64, result[i * 8 ..][0..8], value, .little);
47	    }
48	
49	    return result;
50	}
51	
52	/// Encode f32 values as little-endian 4-byte IEEE 754
53	pub fn encodeFloat(allocator: std.mem.Allocator, values: []const f32) ![]u8 {
54	    const result = try allocator.alloc(u8, values.len * 4);
55	
56	    for (values, 0..) |value, i| {
57	        const bits: u32 = @bitCast(value);
58	        std.mem.writeInt(u32, result[i * 4 ..][0..4], bits, .little);
59	    }
60	
61	    return result;
62	}
