64	/// Encode f64 values as little-endian 8-byte IEEE 754
65	pub fn encodeDouble(allocator: std.mem.Allocator, values: []const f64) ![]u8 {
66	    const result = try allocator.alloc(u8, values.len * 8);
67	
68	    for (values, 0..) |value, i| {
69	        const bits: u64 = @bitCast(value);
70	        std.mem.writeInt(u64, result[i * 8 ..][0..8], bits, .little);
71	    }
72	
73	    return result;
74	}
75	
76	/// Encode byte arrays with 4-byte length prefix each
77	pub fn encodeByteArrays(allocator: std.mem.Allocator, values: []const []const u8) ![]u8 {
78	    // Calculate total size
79	    var total_size: usize = 0;
80	    for (values) |value| {
81	        if (value.len > std.math.maxInt(i32)) return error.ValueTooLarge;
82	        const entry_size = std.math.add(usize, 4, value.len) catch return error.OutOfMemory;
83	        total_size = std.math.add(usize, total_size, entry_size) catch return error.OutOfMemory;
84	    }
85	
86	    const result = try allocator.alloc(u8, total_size);
87	    var pos: usize = 0;
88	
89	    for (values) |value| {
90	        // Write length as u32 little-endian
91	        std.mem.writeInt(u32, result[pos..][0..4], try safe.castTo(u32, value.len), .little);
92	        pos += 4;
93	
94	        // Write data
95	        @memcpy(result[pos..][0..value.len], value);
96	        pos += value.len;
97	    }
98	
99	    return result;
100	}
101	
102	/// Encode fixed-length byte arrays (no length prefix)
103	pub fn encodeFixedByteArrays(allocator: std.mem.Allocator, values: []const []const u8, fixed_len: usize) ![]u8 {
104	    if (fixed_len > std.math.maxInt(i32)) return error.ValueTooLarge;
105	    const result = try allocator.alloc(u8, values.len * fixed_len);
106	
107	    for (values, 0..) |value, i| {
108	        if (value.len != fixed_len) {
109	            return error.InvalidFixedLength;
110	        }
111	        @memcpy(result[i * fixed_len ..][0..fixed_len], value);
112	    }
113	
114	    return result;
115	}
