11	/// Generic statistics builder for primitive types.
12	/// Tracks min/max values and null count during column writing.
13	pub fn StatisticsBuilder(comptime T: type) type {
14	    return struct {
15	        min: ?T = null,
16	        max: ?T = null,
17	        null_count: i64 = 0,
18	        has_values: bool = false,
19	
20	        const Self = @This();
21	
22	        /// Update statistics with a slice of non-null values.
23	        pub fn update(self: *Self, values: []const T) void {
24	            for (values) |v| {
25	                self.updateValue(v);
26	            }
27	        }
28	
29	        /// Update statistics with a single value.
30	        fn updateValue(self: *Self, value: T) void {
31	            if ((T == f32 or T == f64) and std.math.isNan(value)) return;
32	            if (!self.has_values) {
33	                self.min = value;
34	                self.max = value;
35	                self.has_values = true;
36	            } else {
37	                if (compare(value, self.min.?) == .lt) {
38	                    self.min = value;
39	                }
40	                if (compare(value, self.max.?) == .gt) {
41	                    self.max = value;
42	                }
43	            }
44	        }
45	
46	        /// Update statistics with a slice of nullable values.
47	        /// Deprecated: Use updateOptional with Optional(T) instead.
48	        fn updateNullable(self: *Self, values: []const ?T) void {
49	            for (values) |v| {
50	                if (v) |val| {
51	                    self.updateValue(val);
52	                } else {
53	                    self.null_count += 1;
54	                }
55	            }
56	        }
57	
58	        /// Update statistics with a slice of Optional values (unified API).
59	        /// This is the preferred method - accepts the same Optional(T) type that Reader returns.
60	        pub fn updateOptional(self: *Self, values: []const Optional(T)) void {
61	            for (values) |v| {
62	                switch (v) {
63	                    .value => |val| self.updateValue(val),
64	                    .null_value => self.null_count += 1,
65	                }
66	            }
67	        }
68	
69	        /// Add to null count (for cases where nulls are tracked separately).
70	        pub fn addNulls(self: *Self, count: i64) void {
71	            self.null_count += count;
72	        }
73	
74	        /// Build the Statistics struct with PLAIN-encoded min/max values.
75	        /// Returns null if no values were recorded.
76	        pub fn build(self: *const Self, allocator: std.mem.Allocator) !?format.Statistics {
77	            if (!self.has_values) {
78	                // No values - only return null_count if we have nulls
79	                if (self.null_count > 0) {
80	                    return format.Statistics{
81	                        .null_count = self.null_count,
82	                    };
83	                }
84	                return null;
85	            }
86	
87	            const min_bytes = try encodeValue(allocator, self.min.?);
88	            errdefer allocator.free(min_bytes);
89	
90	            const max_bytes = try encodeValue(allocator, self.max.?);
91	            errdefer allocator.free(max_bytes);
92	
93	            // Duplicate for deprecated fields (both point to same encoded value)
94	            const min_deprecated = try allocator.dupe(u8, min_bytes);
95	            errdefer allocator.free(min_deprecated);
96	
97	            const max_deprecated = try allocator.dupe(u8, max_bytes);
98	
99	            return format.Statistics{
100	                .min = min_deprecated, // deprecated field
101	                .max = max_deprecated, // deprecated field
102	                .null_count = self.null_count,
103	                .distinct_count = null,
104	                .min_value = min_bytes, // current standard
105	                .max_value = max_bytes, // current standard
106	            };
107	        }
108	
109	        /// Compare two values of type T.
110	        fn compare(a: T, b: T) std.math.Order {
111	            if (T == bool) {
112	                // false < true
113	                const a_int: u1 = if (a) 1 else 0;
114	                const b_int: u1 = if (b) 1 else 0;
115	                return std.math.order(a_int, b_int);
116	            } else if (T == []const u8) {
117	                // Lexicographic byte comparison
118	                return std.mem.order(u8, a, b);
119	            } else {
120	                // Numeric types: use standard comparison
121	                return std.math.order(a, b);
122	            }
123	        }
124	
125	        /// Encode a value to bytes using PLAIN encoding.
126	        fn encodeValue(allocator: std.mem.Allocator, value: T) ![]u8 {
127	            if (T == i32) {
128	                const bytes = try allocator.alloc(u8, 4);
129	                std.mem.writeInt(i32, bytes[0..4], value, .little);
130	                return bytes;
131	            } else if (T == i64) {
132	                const bytes = try allocator.alloc(u8, 8);
133	                std.mem.writeInt(i64, bytes[0..8], value, .little);
134	                return bytes;
135	            } else if (T == f32) {
136	                const bytes = try allocator.alloc(u8, 4);
137	                const bits: u32 = @bitCast(value);
138	                std.mem.writeInt(u32, bytes[0..4], bits, .little);
139	                return bytes;
140	            } else if (T == f64) {
141	                const bytes = try allocator.alloc(u8, 8);
142	                const bits: u64 = @bitCast(value);
143	                std.mem.writeInt(u64, bytes[0..8], bits, .little);
144	                return bytes;
145	            } else if (T == bool) {
146	                const bytes = try allocator.alloc(u8, 1);
147	                bytes[0] = if (value) 1 else 0;
148	                return bytes;
149	            } else if (T == []const u8) {
150	                // Byte arrays: copy raw bytes (no length prefix in statistics)
151	                return try allocator.dupe(u8, value);
152	            } else {
153	                @compileError("Unsupported type for statistics: " ++ @typeName(T));
154	            }
155	        }
156	    };
157	}
