161	pub const ByteArrayStatisticsBuilder = struct {
162	    min: ?[]u8 = null,
163	    max: ?[]u8 = null,
164	    null_count: i64 = 0,
165	    has_values: bool = false,
166	    allocator: std.mem.Allocator,
167	
168	    const Self = @This();
169	
170	    pub fn init(allocator: std.mem.Allocator) Self {
171	        return .{ .allocator = allocator };
172	    }
173	
174	    pub fn deinit(self: *Self) void {
175	        if (self.min) |m| self.allocator.free(m);
176	        if (self.max) |m| self.allocator.free(m);
177	    }
178	
179	    /// Update statistics with a slice of byte array values.
180	    pub fn update(self: *Self, values: []const []const u8) !void {
181	        for (values) |v| {
182	            try self.updateValue(v);
183	        }
184	    }
185	
186	    /// Update statistics with a single byte array value.
187	    fn updateValue(self: *Self, value: []const u8) !void {
188	        if (!self.has_values) {
189	            self.min = try self.allocator.dupe(u8, value);
190	            errdefer {
191	                self.allocator.free(self.min.?);
192	                self.min = null;
193	            }
194	            self.max = try self.allocator.dupe(u8, value);
195	            self.has_values = true;
196	        } else {
197	            if (std.mem.order(u8, value, self.min.?) == .lt) {
198	                self.allocator.free(self.min.?);
199	                self.min = null;
200	                self.min = try self.allocator.dupe(u8, value);
201	            }
202	            if (std.mem.order(u8, value, self.max.?) == .gt) {
203	                self.allocator.free(self.max.?);
204	                self.max = null;
205	                self.max = try self.allocator.dupe(u8, value);
206	            }
207	        }
208	    }
209	
210	    /// Update statistics with a slice of nullable byte array values.
211	    /// Deprecated: Use updateOptional with Optional([]const u8) instead.
212	    fn updateNullable(self: *Self, values: []const ?[]const u8) !void {
213	        for (values) |v| {
214	            if (v) |val| {
215	                try self.updateValue(val);
216	            } else {
217	                self.null_count += 1;
218	            }
219	        }
220	    }
221	
222	    /// Update statistics with a slice of Optional byte array values (unified API).
223	    /// This is the preferred method - accepts the same Optional type that Reader returns.
224	    pub fn updateOptional(self: *Self, values: []const Optional([]const u8)) !void {
225	        for (values) |v| {
226	            switch (v) {
227	                .value => |val| try self.updateValue(val),
228	                .null_value => self.null_count += 1,
229	            }
230	        }
231	    }
232	
233	    /// Add to null count.
234	    pub fn addNulls(self: *Self, count: i64) void {
235	        self.null_count += count;
236	    }
237	
238	    /// Build the Statistics struct.
239	    /// Ownership of min/max bytes is transferred to the returned Statistics.
240	    pub fn build(self: *Self) ?format.Statistics {
241	        if (!self.has_values) {
242	            if (self.null_count > 0) {
243	                return format.Statistics{
244	                    .null_count = self.null_count,
245	                };
246	            }
247	            return null;
248	        }
249	
250	        const min_bytes = self.min orelse return null;
251	        const max_bytes = self.max orelse return null;
252	
253	        // Duplicate for deprecated fields
254	        const min_deprecated = self.allocator.dupe(u8, min_bytes) catch return null;
255	        const max_deprecated = self.allocator.dupe(u8, max_bytes) catch {
256	            self.allocator.free(min_deprecated);
257	            return null;
258	        };
259	
260	        // Clear our references since we're transferring ownership
261	        self.min = null;
262	        self.max = null;
263	
264	        return format.Statistics{
265	            .min = min_deprecated,
266	            .max = max_deprecated,
267	            .null_count = self.null_count,
268	            .distinct_count = null,
269	            .min_value = min_bytes,
270	            .max_value = max_bytes,
271	        };
272	    }
273	};
