787	    pub fn addRow(self: *DynamicWriter) DynamicWriterError!void {
788	        if (!self.began) return error.InvalidState;
789	        for (0..self.num_columns) |i| {
790	            if (!self.row_set[i]) {
791	                if (self.column_required[i]) return error.InvalidArgument;
792	                self.current_row[i] = .null_val;
793	            }
794	            self.column_buffers[i].append(self.allocator, self.current_row[i]) catch return error.OutOfMemory;
795	            self.current_row[i] = .null_val;
796	            self.row_set[i] = false;
797	        }
798	        self.rows_in_current_group += 1;
799	        if (self.row_group_row_limit) |limit| {
800	            if (self.rows_in_current_group >= limit) {
801	                try self.flush();
802	            }
803	        }
