823	            if (meta.dictionary_page_offset) |d_off| {
824	                if (d_off > 0) break :blk meta.data_page_offset - d_off;
825	            }
826	            break :blk 0;
827	        };
828	        const total_i64 = safe.castTo(i64, result.total_bytes) catch return error.IntegerOverflow;
829	        const data_page_compressed = total_i64 - dict_bytes;
830	        if (data_page_compressed <= 0) return; // defensive
831	
832	        var min_bytes: []const u8 = &.{};
833	        var max_bytes: []const u8 = &.{};
