845	            }
846	            if (null_count == safe.castTo(i64, n) catch @as(i64, std.math.maxInt(i32))) {
847	                all_null = true;
848	            }
849	        }
850	
851	        const data_page_compressed_i32 = safe.castTo(i32, data_page_compressed) catch return error.IntegerOverflow;
852	        const n_i64 = safe.castTo(i64, n) catch return error.TooManyValues;
