880	    pub fn flush(self: *DynamicWriter) DynamicWriterError!void {
881	        if (!self.began) return error.InvalidState;
882	        if (self.column_buffers.len == 0) return;
883	        const n = self.column_buffers[0].items.len;
884	        if (n == 0) return;
885	
886	        const allocator = self.allocator;
887	        const writer = self.target_writer.writer();
888	        const row_group_offset = self.current_offset;
889	
890	        var col_chunks_list: std.ArrayListUnmanaged(format.ColumnChunk) = .empty;
891	        errdefer {
892	            for (col_chunks_list.items) |cc| {
893	                if (cc.meta_data) |meta| {
894	                    allocator.free(meta.encodings);
895	                    for (meta.path_in_schema) |p| allocator.free(p);
896	                    allocator.free(meta.path_in_schema);
897	                }
898	            }
899	            col_chunks_list.deinit(allocator);
900	        }
901	
902	        // Page-index builders for this row group. Left as all-null when
903	        // write_page_index is off; each populated slot corresponds to a flat
904	        // column chunk we know how to index (single-page, non-nested).
905	        var pi_builders: ?[]?page_index_writer.PageIndexBuilder = null;
906	        errdefer if (pi_builders) |pb| {
907	            for (pb) |*maybe| if (maybe.*) |*b| b.deinit();
908	            allocator.free(pb);
909	        };
910	        if (self.write_page_index) {
911	            const leaf_count = try self.countLeafColumns();
912	            const builders = allocator.alloc(?page_index_writer.PageIndexBuilder, leaf_count) catch return error.OutOfMemory;
913	            @memset(builders, null);
914	            pi_builders = builders;
915	        }
916	
917	        var total_byte_size: i64 = 0;
918	
919	        for (0..self.num_columns) |col| {
920	            const items = self.column_buffers[col].items;
921	            const codec = self.column_codecs[col];
922	            const col_name = self.column_names_owned[col];
923	
924	            if (self.column_types[col] == .nested) {
925	                const node = self.column_schema_nodes[col] orelse return error.InvalidState;
926	                try self.flushNestedColumn(&col_chunks_list, items, n, node, col, col_name, codec, &total_byte_size);
927	            } else {
928	                const path: []const []const u8 = &.{col_name};
929	                const opts = self.resolveOpts(col, &.{col_name});
930	                const is_optional = !self.column_required[col];
931	
932	                // Pre-create the builder so column_writer can populate per-page
933	                // entries directly (multi-page path).
934	                const leaf_idx = col_chunks_list.items.len;
935	                var pib_ptr: ?*page_index_writer.PageIndexBuilder = null;
936	                if (pi_builders) |pb| {
937	                    const phys = self.column_types[col].toPhysicalType() orelse return error.InvalidState;
938	                    pb[leaf_idx] = page_index_writer.PageIndexBuilder.init(allocator, phys, true);
939	                    pib_ptr = &pb[leaf_idx].?;
940	                }
941	
942	                const result: column_writer.ColumnChunkResult = switch (self.column_types[col]) {
943	                    .bool_ => flushColumnBool(allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts) catch |e| return mapFlushError(e),
944	                    .int32 => flushColumnTyped(i32, allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts, pib_ptr) catch |e| return mapFlushError(e),
945	                    .int64 => flushColumnTyped(i64, allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts, pib_ptr) catch |e| return mapFlushError(e),
946	                    .float_ => flushColumnTyped(f32, allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts, pib_ptr) catch |e| return mapFlushError(e),
947	                    .double_ => flushColumnTyped(f64, allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts, pib_ptr) catch |e| return mapFlushError(e),
948	                    .bytes => flushColumnBytes(allocator, writer, path, items, n, self.current_offset, codec, is_optional, opts) catch |e| return mapFlushError(e),
949	                    .fixed_bytes => flushColumnFixedBytes(
950	                        allocator, writer, path, items, n, self.current_offset, codec,
951	                        self.column_type_lengths[col] orelse return error.InvalidState, is_optional, opts,
952	                    ) catch |e| return mapFlushError(e),
953	                    .nested => return error.InvalidState,
954	                };
955	
956	                self.target_writer.flush() catch return error.WriteError;
957	
958	                col_chunks_list.append(allocator, .{
959	                    .file_path = null,
960	                    .file_offset = result.file_offset,
961	                    .meta_data = result.metadata,
962	                }) catch return error.OutOfMemory;
963	                total_byte_size += result.metadata.total_compressed_size;
964	                self.current_offset += safe.castTo(i64, result.total_bytes) catch return error.IntegerOverflow;
965	
966	                // If column_writer didn't populate the builder (dict path,
967	                // bytes, bool, fixed_bytes), fall back to a single entry
968	                // built from the chunk-level metadata.
969	                if (pib_ptr) |pib| {
970	                    if (pib.pageCount() == 0) {
971	                        try self.recordFlatPageInto(pib, &result, n);
972	                    }
973	                }
974	            }
975	        }
976	
977	        const col_chunks = col_chunks_list.toOwnedSlice(allocator) catch return error.OutOfMemory;
978	
979	        self.row_groups.append(allocator, .{
980	            .columns = col_chunks,
981	            .num_rows = safe.castTo(i64, n) catch return error.TooManyValues,
982	            .total_byte_size = total_byte_size,
983	            .file_offset = row_group_offset,
984	        }) catch {
985	            allocator.free(col_chunks);
986	            return error.OutOfMemory;
987	        };
988	
989	        // Transfer page-index builders for this row group into self's list.
990	        // `pi_builders` is null when the feature is off; otherwise we always
991	        // append a parallel slot (even if some entries are null for nested
992	        // columns we don't index yet).
993	        if (pi_builders) |pb| {
994	            self.page_index_builders.append(allocator, pb) catch {
995	                for (pb) |*maybe| if (maybe.*) |*b| b.deinit();
996	                allocator.free(pb);
997	                return error.OutOfMemory;
998	            };
999	            pi_builders = null;
1000	        }
1001	
1002	        for (0..self.num_columns) |i| {
1003	            self.column_buffers[i].clearRetainingCapacity();
1004	        }
1005	        _ = self.bytes_arena.reset(.retain_capacity);
1006	        self.rows_in_current_group = 0;
1007	    }
