9	/// Thread-local override for byte payload allocations. When set (typically by
10	/// `DynamicReader.readRowsInternal`), all `bytes_val` / `fixed_bytes_val`
11	/// payloads produced via `dupeBytes` go into this allocator instead of the
12	/// per-value allocator. Paired with `Row.bytes_borrowed = true` so per-value
13	/// frees in `deinit` skip these payloads; the producer frees the arena en
14	/// masse. Save/restore the prior value at each entry point — the pattern is:
15	///
16	///     const prev = value_mod.bytes_arena_allocator;
17	///     value_mod.bytes_arena_allocator = arena.allocator();
18	///     defer value_mod.bytes_arena_allocator = prev;
19	///
20	/// This replaces the per-value `allocator.dupe(u8, ...)` hot path (~440k
21	/// allocations on covid.snappy.parquet) with one arena's worth of contiguous
22	/// allocations, avoiding the N*stack-trace overhead of DebugAllocator.
23	pub threadlocal var bytes_arena_allocator: ?std.mem.Allocator = null;
24	
25	/// Duplicate a byte slice, routing through `bytes_arena_allocator` if set,
26	/// else through the provided `fallback` allocator. Every producer of
27	/// `Value.bytes_val` and `Value.fixed_bytes_val` should call this helper
28	/// instead of `allocator.dupe(u8, ...)` to participate in the arena scheme.
29	pub fn dupeBytes(fallback: std.mem.Allocator, bytes: []const u8) std.mem.Allocator.Error![]u8 {
30	    const alloc = bytes_arena_allocator orelse fallback;
31	    return alloc.dupe(u8, bytes);
32	}
