24	/// Hash context for dictionary keys that supports float types by bitcasting to integers.
25	/// std.AutoHashMap rejects f32/f64; this context hashes their bit patterns instead.
26	fn DictHashContext(comptime K: type) type {
27	    return struct {
28	        pub fn hash(_: @This(), key: K) u64 {
29	            return std.hash.Wyhash.hash(0, std.mem.asBytes(&key));
30	        }
31	        pub fn eql(_: @This(), a: K, b: K) bool {
32	            if (K == f32 or K == f64) {
33	                return std.mem.eql(u8, std.mem.asBytes(&a), std.mem.asBytes(&b));
34	            }
35	            return a == b;
36	        }
37	    };
38	}
