392	pub fn writeColumnChunkByteArrayDictOptionalWithPathArray(
393	    allocator: std.mem.Allocator,
394	    output: *std.Io.Writer,
395	    path_in_schema: []const []const u8,
396	    values: []const Optional([]const u8),
397	    is_optional: bool,
398	    start_offset: i64,
399	    codec: format.CompressionCodec,
400	    dictionary_size_limit: ?usize,
401	    dictionary_cardinality_threshold: ?f32,
402	    max_page_size: ?usize,
403	    write_page_checksum: bool,
404	) ColumnWriteError!ColumnChunkResult {
405	    if (values.len == 0) {
406	        return writeColumnChunkByteArrayOptionalWithPathArray(allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
407	    }
408	
409	    // Compute statistics using unified API
410	    var stats_builder = statistics.ByteArrayStatisticsBuilder.init(allocator);
411	    stats_builder.updateOptional(values) catch return error.OutOfMemory;
412	    var stats = stats_builder.build();
413	    errdefer if (stats) |s| freeStatistics(allocator, s);
414	
415	    // Build dictionary from non-null values
416	    var unique_map = std.StringHashMap(u32).init(allocator);
417	    defer unique_map.deinit();
418	    var dict_values: std.ArrayListUnmanaged([]const u8) = .empty;
419	    defer dict_values.deinit(allocator);
420	
421	    var non_null_count: usize = 0;
422	    for (values) |v| {
423	        if (v != .null_value) non_null_count += 1;
424	    }
425	
426	    var indices = allocator.alloc(u32, non_null_count) catch return error.OutOfMemory;
427	    defer allocator.free(indices);
428	
429	    var dict_bytes: usize = 0;
430	    var idx: usize = 0;
431	    for (values) |v| {
432	        if (v != .null_value) {
433	            const val = v.value;
434	            if (val.len > std.math.maxInt(i32)) return error.ValueTooLarge;
435	            if (unique_map.get(val)) |dict_idx| {
436	                indices[idx] = dict_idx;
437	            } else {
438	                const new_idx: u32 = try safe.castTo(u32, dict_values.items.len);
439	                unique_map.put(val, new_idx) catch return error.OutOfMemory;
440	                dict_values.append(allocator, val) catch return error.OutOfMemory;
441	                dict_bytes += 4 + val.len;
442	                indices[idx] = new_idx;
443	            }
444	            idx += 1;
445	
446	            if (dictionary_cardinality_threshold) |threshold| {
447	                if (idx >= 1024) {
448	                    const ratio = @as(f32, @floatFromInt(dict_values.items.len)) / @as(f32, @floatFromInt(idx));
449	                    if (ratio > threshold) {
450	                        if (stats) |s| freeStatistics(allocator, s);
451	                        stats = null;
452	                        return writeColumnChunkByteArrayOptionalWithPathArray(allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
453	                    }
454	                }
455	            }
456	        }
457	    }
458	
459	    const dict_size = dict_values.items.len;
460	
461	    // Check dictionary size limit
462	    if (dictionary_size_limit) |limit| {
463	        if (dict_bytes > limit) {
464	            if (stats) |s| freeStatistics(allocator, s);
465	            stats = null;
466	            return writeColumnChunkByteArrayOptionalWithPathArray(allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
467	        }
468	    }
469	
470	    // Write dictionary page (length-prefixed byte arrays)
471	    const dict_data = allocator.alloc(u8, dict_bytes) catch return error.OutOfMemory;
472	    defer allocator.free(dict_data);
473	
474	    var dict_offset: usize = 0;
475	    for (dict_values.items) |v| {
476	        std.mem.writeInt(u32, dict_data[dict_offset..][0..4], try safe.castTo(u32, v.len), .little);
477	        dict_offset += 4;
478	        @memcpy(dict_data[dict_offset..][0..v.len], v);
479	        dict_offset += v.len;
480	    }
481	
482	    // Compress dictionary data if needed
483	    const dict_compressed: []const u8 = if (codec == .uncompressed)
484	        dict_data
485	    else blk: {
486	        break :blk compress.compress(allocator, dict_data, codec) catch |err| switch (err) {
487	            error.UnsupportedCompression => return error.UnsupportedCompression,
488	            error.CompressionError => return error.CompressionError,
489	            error.OutOfMemory => return error.OutOfMemory,
490	        };
491	    };
492	    defer if (codec != .uncompressed) allocator.free(dict_compressed);
493	
494	    // Write dictionary page header
495	    const dict_page_header = format.PageHeader{
496	        .type_ = .dictionary_page,
497	        .uncompressed_page_size = try safe.castTo(i32, dict_data.len),
498	        .compressed_page_size = try safe.castTo(i32, dict_compressed.len),
499	        .crc = if (write_page_checksum) computePageCrc(dict_compressed) else null,
500	        .data_page_header = null,
501	        .dictionary_page_header = .{
502	            .num_values = try safe.castTo(i32, dict_size),
503	            .encoding = .plain,
504	            .is_sorted = false,
