515	
516	    var total_bytes_written: usize = dict_header_bytes.len + dict_compressed.len;
517	    var total_uncompressed_written: usize = dict_header_bytes.len + dict_data.len;
518	    const dict_page_offset = start_offset;
519	    const data_page_offset = start_offset + try safe.castTo(i64, total_bytes_written);
520	
521	    // Compute bit width for indices
522	    const bit_width: u5 = if (dict_size <= 1) 0 else try safe.castTo(u5, std.math.log2_int(usize, dict_size - 1) + 1);
523	
524	    // Calculate values per page
525	    const values_per_page: usize = if (max_page_size) |max_size| blk: {
526	        const bytes_per_value_estimate: usize = 3;
527	        const usable_size = if (max_size > 20) max_size - 20 else max_size;
