536	    while (value_offset < values.len) {
537	        const page_end = @min(value_offset + values_per_page, values.len);
538	        const page_values = values[value_offset..page_end];
539	
540	        // Count non-null values in this page
541	        var page_non_null_count: usize = 0;
542	        for (page_values) |v| {
543	            if (v != .null_value) page_non_null_count += 1;
544	        }
545	
546	        // Get indices for this page
547	        const page_indices = indices[index_offset .. index_offset + page_non_null_count];
548	        index_offset += page_non_null_count;
