559	            for (page_values, 0..) |v, i| {
560	                page_def_levels[i] = v != .null_value;
561	            }
562	
563	            const def_level_data = rle_encoder.encodeDefLevelsWithLength(allocator, page_def_levels) catch return error.OutOfMemory;
