574	            @memcpy(page_data[1..], rle_data);
575	            break :blk page_data;
576	        };
577	        defer allocator.free(data_page_uncompressed);
578	
579	        // Compress data page if needed
580	        const data_compressed: []const u8 = if (codec == .uncompressed)
581	            data_page_uncompressed
582	        else cblk: {
583	            break :cblk compress.compress(allocator, data_page_uncompressed, codec) catch |err| switch (err) {
584	                error.UnsupportedCompression => return error.UnsupportedCompression,
585	                error.CompressionError => return error.CompressionError,
586	                error.OutOfMemory => return error.OutOfMemory,
587	            };
588	        };
589	        defer if (codec != .uncompressed) allocator.free(data_compressed);
590	
591	        // Write data page header
592	        const data_page_header = format.PageHeader{
593	            .type_ = .data_page,
594	            .uncompressed_page_size = try safe.castTo(i32, data_page_uncompressed.len),
595	            .compressed_page_size = try safe.castTo(i32, data_compressed.len),
596	            .crc = if (write_page_checksum) computePageCrc(data_compressed) else null,
597	            .data_page_header = .{
598	                .num_values = try safe.castTo(i32, page_values.len),
