602	                .statistics = null,
603	            },
604	            .dictionary_page_header = null,
605	        };
606	
607	        var data_thrift = thrift.CompactWriter.init(allocator);
608	        defer data_thrift.deinit();
609	        data_page_header.serialize(&data_thrift) catch return error.OutOfMemory;
610	        const data_header_bytes = data_thrift.getWritten();
