641	            .total_compressed_size = try safe.castTo(i64, total_bytes_written),
642	            .data_page_offset = data_page_offset,
643	            .index_page_offset = null,
644	            .dictionary_page_offset = dict_page_offset,
645	            .statistics = stats,
