1	//! Thrift Compact Protocol encoder
2	//!
3	//! The Compact Protocol is a binary protocol that uses variable-length encoding
4	//! for integers and packs field headers efficiently.
5	//!
6	//! This is the inverse of CompactReader - used for serializing Parquet metadata.
7	
8	const std = @import("std");
9	const safe = @import("../safe.zig");
10	const compact = @import("compact.zig");
11	const Type = compact.Type;
12	
13	/// A writer for Thrift Compact Protocol encoded data
14	pub const CompactWriter = struct {
15	    buffer: std.ArrayList(u8),
16	    allocator: std.mem.Allocator,
17	    last_field_id: i16 = 0,
18	
19	    const Self = @This();
20	
21	    pub fn init(allocator: std.mem.Allocator) Self {
22	        return .{
23	            .buffer = .empty,
24	            .allocator = allocator,
25	        };
26	    }
27	
28	    pub fn deinit(self: *Self) void {
29	        self.buffer.deinit(self.allocator);
30	    }
31	
32	    /// Get the written bytes
33	    pub fn getWritten(self: *const Self) []const u8 {
34	        return self.buffer.items;
35	    }
36	
37	    /// Reset the writer for reuse
38	    pub fn reset(self: *Self) void {
39	        self.buffer.clearRetainingCapacity();
40	        self.last_field_id = 0;
41	    }
42	
43	    /// Write a single byte
44	    pub fn writeByte(self: *Self, b: u8) !void {
45	        try self.buffer.append(self.allocator, b);
46	    }
47	
48	    /// Write multiple bytes
49	    fn writeBytes(self: *Self, bytes: []const u8) !void {
50	        try self.buffer.appendSlice(self.allocator, bytes);
51	    }
52	
53	    /// Write an unsigned variable-length integer (varint)
54	    pub fn writeVarInt(self: *Self, value: u64) !void {
55	        var v = value;
56	        while (v >= 0x80) {
57	            try self.writeByte(@as(u8, @truncate(v)) | 0x80);
58	            v >>= 7;
59	        }
60	        try self.writeByte(@truncate(v));
61	    }
62	
63	    /// Encode a signed integer using zigzag encoding
64	    fn zigzagEncode(n: i64) u64 {
65	        const un: u64 = @bitCast(n);
66	        return (un << 1) ^ @as(u64, @bitCast(n >> 63));
67	    }
68	
69	    /// Write a signed 16-bit integer (zigzag + varint)
70	    pub fn writeI16(self: *Self, value: i16) !void {
71	        try self.writeVarInt(zigzagEncode(value));
72	    }
73	
74	    /// Write a signed 32-bit integer (zigzag + varint)
75	    pub fn writeI32(self: *Self, value: i32) !void {
76	        try self.writeVarInt(zigzagEncode(value));
77	    }
78	
79	    /// Write a signed 64-bit integer (zigzag + varint)
80	    pub fn writeI64(self: *Self, value: i64) !void {
81	        try self.writeVarInt(zigzagEncode(value));
82	    }
83	
84	    /// Write an 8-byte double (little-endian)
85	    pub fn writeDouble(self: *Self, value: f64) !void {
86	        var buf: [8]u8 = undefined;
87	        std.mem.writeInt(u64, &buf, @bitCast(value), .little);
88	        try self.writeBytes(&buf);
89	    }
90	
91	    /// Write a length-prefixed binary blob
92	    pub fn writeBinary(self: *Self, data: []const u8) !void {
93	        try self.writeVarInt(data.len);
94	        try self.writeBytes(data);
95	    }
96	
97	    /// Write a length-prefixed string (same as binary)
98	    pub fn writeString(self: *Self, str: []const u8) !void {
99	        try self.writeBinary(str);
100	    }
101	
102	    /// Write a field header with delta encoding
103	    pub fn writeFieldHeader(self: *Self, field_id: i16, field_type: Type) !void {
104	        const delta = field_id - self.last_field_id;
105	
106	        if (delta > 0 and delta <= 15) {
107	            // Delta fits in high nibble
108	        const header: u8 = (@as(u8, safe.castTo(u8, delta) catch unreachable) << 4) | @intFromEnum(field_type); // delta is 1..15 from check above
109	            try self.writeByte(header);
110	        } else {
111	            // Write type nibble with 0 delta, then full field ID
112	            try self.writeByte(@intFromEnum(field_type));
113	            try self.writeI16(field_id);
114	        }
115	
116	        self.last_field_id = field_id;
117	    }
118	
119	    /// Write a boolean field (type encodes the value)
120	    pub fn writeBoolField(self: *Self, field_id: i16, value: bool) !void {
121	        const field_type: Type = if (value) .bool_true else .bool_false;
122	        try self.writeFieldHeader(field_id, field_type);
123	    }
124	
125	    /// Write a struct end marker (STOP field)
126	    pub fn writeStructEnd(self: *Self) !void {
127	        try self.writeByte(0x00);
128	    }
129	
130	    /// Write a list header
131	    pub fn writeListHeader(self: *Self, element_type: Type, size: u32) !void {
132	        const type_nibble: u8 = @intFromEnum(element_type);
133	        if (size < 15) {
134	            // Size fits in high nibble
135	            const header: u8 = (@as(u8, safe.castTo(u8, size) catch unreachable) << 4) | type_nibble; // size < 15 from check above
136	            try self.writeByte(header);
137	        } else {
138	            // Size in separate varint
139	            const header: u8 = 0xF0 | type_nibble;
140	            try self.writeByte(header);
141	            try self.writeVarInt(size);
142	        }
143	    }
144	
145	    /// Reset field ID tracking (call when entering a new struct)
146	    pub fn resetFieldTracking(self: *Self) void {
147	        self.last_field_id = 0;
148	    }
149	
150	    /// Save current field ID (for nested structs)
151	    pub fn saveFieldId(self: *const Self) i16 {
152	        return self.last_field_id;
153	    }
154	
155	    /// Restore field ID (after nested struct)
156	    pub fn restoreFieldId(self: *Self, saved: i16) void {
157	        self.last_field_id = saved;
158	    }
159	};
