210	                }
211	            } else {
212	                // Match fields by name
213	                for (s.fields) |schema_field| {
214	                    var found = false;
215	                    for (fields.?) |value_field| {
216	                        if (std.mem.eql(u8, schema_field.name, value_field.name)) {
217	                            try flattenRecursive(schema_field.node, value_field.value, ctx, is_repeated, depth + 1);
