219	                            break;
220	                        }
221	                    }
222	                    if (!found) {
223	                        // Field not present, write null
224	                        try writeNullToLeaves(schema_field.node, ctx);
225	                    }
226	                    ctx.column_index += schema_field.node.countLeafColumns();
227	                }
228	                // Reset column index
229	                for (s.fields) |f| {
230	                    ctx.column_index -= f.node.countLeafColumns();
231	                }
232	            }
233	        },
234	        // Primitive types - write to column
235	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
